photo_dir = "."   # folder where your photos are stored

success, failed = [], []
for i, filename in enumerate(photos):
    path = os.path.join(photo_dir, filename)
    if not os.path.exists(path):
        print(f"[{i+1}/{len(photos)}] NOT FOUND: {filename}")
        failed.append(filename)
        continue
    try:
        result = cloudinary.uploader.upload(
            path,
            folder=FOLDER,
            public_id=filename.replace(".jpg","").replace(".jpeg",""),
            overwrite=False,
            resource_type="image"
        )
        print(f"[{i+1}/{len(photos)}] ✅ {filename}")
        success.append(filename)
    except Exception as e:
        print(f"[{i+1}/{len(photos)}] ❌ {filename}: {e}")
        failed.append(filename)

print(f"\nDone. {len(success)} uploaded, {len(failed)} failed/skipped.")
if failed:
    print("Failed files:", failed)
print(f"\nYour photo base URL:")
print(f"  https://res.cloudinary.com/{CLOUD_NAME}/image/upload/{FOLDER}/")
